package com.learnagent.job;

import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity@Table(name="agent_jobs")public class AgentJob{@Id private UUID id;@Column(name="job_type",nullable=false)private String jobType;@Enumerated(EnumType.STRING)@Column(nullable=false)private AgentJobStatus status;@Column(nullable=false)private int progress;@Column(name="input_json",nullable=false,columnDefinition="text")private String inputJson;@Column(name="result_json",columnDefinition="text")private String resultJson;@Column(name="log_text",nullable=false,columnDefinition="text")private String logText;@Column(name="error_message",columnDefinition="text")private String errorMessage;@Column(name="created_at",nullable=false)private Instant createdAt;@Column(name="started_at")private Instant startedAt;@Column(name="completed_at")private Instant completedAt;@Column(name="dedup_key",unique=true)private String dedupKey;protected AgentJob(){}public AgentJob(String type,String input,String dedup){id=UUID.randomUUID();jobType=type;inputJson=input;dedupKey=dedup;status=AgentJobStatus.PENDING;progress=0;logText="";createdAt=Instant.now();}public void start(){status=AgentJobStatus.RUNNING;startedAt=Instant.now();progress=5;}public void progress(int value,String line){progress=Math.max(progress,Math.min(value,99));if(line!=null&&!line.isBlank())logText+=(logText.isBlank()?"":"\n")+line;}public void succeed(String result){status=AgentJobStatus.SUCCESS;resultJson=result;progress=100;completedAt=Instant.now();}public void fail(String error){status=AgentJobStatus.FAILED;errorMessage=error;completedAt=Instant.now();}public void clearDedupKey(){dedupKey=null;}public UUID getId(){return id;}public String getJobType(){return jobType;}public AgentJobStatus getStatus(){return status;}public int getProgress(){return progress;}public String getInputJson(){return inputJson;}public String getResultJson(){return resultJson;}public String getLogText(){return logText;}public String getErrorMessage(){return errorMessage;}public Instant getCreatedAt(){return createdAt;}public Instant getStartedAt(){return startedAt;}public Instant getCompletedAt(){return completedAt;}}
